    },
    "cli.cmd.locations.setArchives.abstract" : {
      "en" : "Point new Archives at a directory (IDECustomDistributionArchivesLocation; reproduced on Xcode 26.5, status: probable). Existing archives are not moved — use `externalize --category archives`.",
